pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress in the stream
    let progress = step_index as f64 / total_items as f64;
    let time_factor = (1.0 - progress).powf(1.7);

    // Basic waste penalty
    let base = post_residual as f64;

    // Residual ratio after placement
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Early‑stage reward for keeping large residuals
    let early_favor = -4.0
        * time_factor
        * residual_ratio
        * bin_capacity as f64
        * (open_bins_count as f64 + 1.0).sqrt();

    // Penalise bins with many alternatives
    let unique_penalty = 1.2 * fitting_bins_count as f64;

    // Look‑ahead gap to the next item
    let gap_to_next = ((next_item_size as i32 - post_residual as i32).max(0)) as f64;
    let lookahead_pen = gap_to_next * 3.0 * (1.0 - time_factor).max(0.0);

    // Deviation from mean residual
    let mean_deviation = (mean_residual - post_residual as f64).abs();
    let mean_penalty = 0.12 * mean_deviation;

    // Reward residuals close to the next item
    let closeness = (post_residual as i32 - next_item_size as i32).abs() as f64;
    let closeness_reward = -0.5 * closeness;

    // Non‑linear waste penalty
    let waste_penalty = 2.5 * residual_ratio.powf(1.2);

    // Few‑open‑bins preference
    let bin_count_penalty = 0.08 * open_bins_count as f64;

    // New‑bin penalty (only when bin is empty)
    let new_bin_penalty = if bin_residual == bin_capacity {
        5.0
            + 0.4 * open_bins_count as f64
            + 0.5 * mean_residual
            + 0.3 * (open_bins_count as f64).sqrt()
    } else {
        0.0
    };

    // Extra penalty if no bin can fit the item
    let no_fit_penalty = if fitting_bins_count == 0 { 10.0 } else { 0.0 };

    base
        + early_favor
        + unique_penalty
        + lookahead_pen
        + mean_penalty
        + closeness_reward
        + waste_penalty
        + bin_count_penalty
        + new_bin_penalty
        + no_fit_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress factor: recent items are weighted more heavily
    let progress = step_index as f64 / total_items as f64;
    let time_factor = (1.0 - progress).powf(1.5);

    // Basic waste score
    let waste = post_residual as f64;

    // Residual ratio after placing the item
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits, penalise loose fits
    let fit_reward = -(1.0 - residual_ratio).powf(1.4) * bin_capacity as f64 * 0.8;

    // Late‑stage bonus for preserving large residuals
    let late_favor = -2.5
        * time_factor
        * residual_ratio
        * bin_capacity as f64
        * (open_bins_count as f64 + 0.5).sqrt();

    // Penalty for bins that have many alternatives
    let alternative_pen = 1.1 * (fitting_bins_count as f64).sqrt();

    // Look‑ahead gap penalty (too large a gap is bad)
    let gap = ((next_item_size as i32 - post_residual as i32).max(0)) as f64;
    let lookahead_pen = gap * 2.0 * (1.0 - time_factor).max(0.0);

    // Deviation from the average residual
    let mean_dev = (mean_residual - post_residual as f64).abs();
    let mean_pen = 0.08 * mean_dev;

    // Reward residuals that are close to the next item
    let closeness = (post_residual as i32 - next_item_size as i32).abs() as f64;
    let closeness_rev = -0.4 * closeness;

    // Additional gap penalty or reward relative to next item
    let diff = (post_residual as i32 - next_item_size as i32) as f64;
    let diff_pen = if diff > 0.0 { diff * 0.3 } else { diff.abs() * -0.25 };

    // Non‑linear waste penalty
    let waste_pen = 1.5 * residual_ratio.powf(1.3);

    // Preference for fewer open bins
    let bin_count_pen = 0.05 * open_bins_count as f64;

    // New‑bin penalty (only when the bin is empty)
    let new_bin_pen = if bin_residual == bin_capacity {
        3.5
            + 0.25 * open_bins_count as f64
            + 0.35 * mean_residual
            + 0.2 * (open_bins_count as f64).sqrt()
    } else {
        0.0
    };

    // Extra penalty if no bin can fit the item
    let no_fit_pen = if fitting_bins_count == 0 { 7.0 } else { 0.0 };

    // Minor penalty for extremely tight residuals (may block future items)
    let tight_pen = if residual_ratio < 0.1 { 0.5 } else { 0.0 };

    waste
        + fit_reward
        + late_favor
        + alternative_pen
        + lookahead_pen
        + mean_pen
        + closeness_rev
        + diff_pen
        + waste_pen
        + bin_count_pen
        + new_bin_pen
        + no_fit_pen
        + tight_pen
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress in the stream
    let progress = step_index as f64 / total_items as f64;
    let early_weight = (1.0 - progress).powi(2) * 1.2;

    // Residual ratios
    let residual_before = bin_residual as f64 / bin_capacity as f64;
    let residual_after  = post_residual as f64 / bin_capacity as f64;

    // Base waste
    let waste = post_residual as f64;

    // 1️⃣ Early‑fit bias: prefer larger residuals early
    let early_bias = -2.7 * early_weight * residual_after * (open_bins_count as f64).sqrt();

    // 2️⃣ Unique‑fit penalty: bins with many alternatives are less attractive
    let unique_penalty = if fitting_bins_count > 1 {
        1.5 * (fitting_bins_count as f64).ln()
    } else {
        0.0
    };

    // 3️⃣ Tight‑fit reward: how well the item fills the bin
    let fit_frac = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    let fit_reward = -3.0 * fit_frac;

    // 4️⃣ Look‑ahead: reward/penalise depending on next item fit
    let lookahead = if next_item_size <= post_residual {
        -1.2 * ((post_residual - next_item_size) as f64).sqrt()
    } else {
        ((next_item_size - post_residual) as f64).powi(3) * 0.02
    };

    // 5️⃣ Mean‑deviation penalty: avoid bins far from average residual
    let mean_dev = (mean_residual - post_residual as f64).abs();
    let mean_penalty = 0.12 * mean_dev;

    // 6️⃣ Closeness reward: residual close to next item size is good
    let closeness = (post_residual as i32 - next_item_size as i32).abs() as f64;
    let closeness_reward = -0.8 * closeness.sqrt();

    // 7️⃣ Residual‑ratio reward: smaller residual after placement is desirable
    let residual_reward = -4.5 * residual_after;

    // 8️⃣ New‑bin penalty – reduced if many bins already open
    let new_bin_penalty = if bin_residual == bin_capacity {
        5.0 + 0.1 * open_bins_count as f64 + 0.03 * mean_residual
    } else {
        0.0
    };

    // 9️⃣ Extra penalty for open bins with residual above the mean
    let open_bin_penalty = if bin_residual == bin_capacity {
        0.0
    } else {
        let excess = residual_before - mean_residual;
        if excess > 0.0 { excess * 0.25 } else { 0.0 }
    };

    waste
        + early_bias
        + unique_penalty
        + fit_reward
        + lookahead
        + mean_penalty
        + closeness_reward
        + residual_reward
        + new_bin_penalty
        + open_bin_penalty
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress of the stream
    let progress = step_index as f64 / total_items as f64;
    let time_factor = (1.0 - progress).powf(1.6);

    // Residual ratios
    let residual_before = bin_residual as f64 / bin_capacity as f64;
    let residual_after  = post_residual as f64 / bin_capacity as f64;
    let used_ratio      = 1.0 - residual_before;

    // Fit fraction (how much of the bin is filled by this item)
    let fit_fraction = (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Base component: remaining space after placement
    let mut score = post_residual as f64;

    // 1. Prefer bins that keep large residuals early
    score -= 2.2 * time_factor * residual_after * bin_capacity as f64 * (open_bins_count as f64).sqrt();

    // 2. Penalize bins with many alternatives
    score += 1.2 * ((fitting_bins_count as f64).ln().max(0.0));

    // 3. Reward tight fits
    score -= 1.3 * (1.0 - fit_fraction);

    // 4. Look‑ahead: penalize or reward based on next item
    let lookahead = if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        diff * diff * 0.015 * (1.0 - progress)
    } else if next_item_size == post_residual {
        -0.5 // perfect fit reward
    } else {
        -0.2 * ((post_residual - next_item_size) as f64).powi(2) * (1.0 - progress)
    };
    score += lookahead;

    // 5. Mean residual alignment
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= 0.2 * mean_diff / mean_residual.max(1.0);

    // 6. Closeness to next item size (linear)
    let closeness = (post_residual as i32 - next_item_size as i32).abs() as f64;
    score -= 0.35 * closeness;

    // 7. Residual ratio reward: encourage very small residual after placement
    score -= 3.0 * residual_after;

    // 8. New‑bin penalty (reduced when many bins already open)
    if bin_residual == bin_capacity {
        score += 2.5 * (1.0 - (open_bins_count as f64).min(40.0) / 40.0)
                 + 0.03 * open_bins_count as f64
                 + 0.015 * mean_residual;
    }

    // 9. Dead‑space penalty for large residual chunks
    if residual_after > 0.3 {
        score += (residual_after - 0.3).powi(2) * 3.5;
    }

    //10. High‑usage reward: strongly reward bins that are almost full
    if used_ratio > 0.96 {
        score -= (used_ratio - 0.96).powi(2) * 10.0;
    }

    score
}

