pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress through the stream
    let progress = step_index as f64 / total_items as f64;
    let future_progress = (step_index + 1) as f64 / total_items as f64;
    let time_decay = (1.0 - progress).powf(2.0);

    // Residuals
    let res_before = bin_residual as f64 / bin_capacity as f64;
    let res_after  = post_residual as f64 / bin_capacity as f64;
    let used_ratio = 1.0 - res_before;
    let fit_fraction = (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Base score: space left after placement
    let mut score = post_residual as f64;

    // 1. Prefer bins that keep larger residuals early
    let early = -3.0
        * time_decay
        * res_after
        * bin_capacity as f64
        * (open_bins_count as f64).sqrt();
    score += early;

    // 2. Penalize bins with many alternatives
    let alt_penalty = 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    score += alt_penalty;

    // 3. Reward tight fits
    let tight = -2.0 * (1.0 - fit_fraction);
    score += tight;

    // 4. Look‑ahead penalty: next item cannot fit in the remaining space
    let lookahead = if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        diff.powi(2) * 0.025 * (1.0 - progress)
    } else {
        0.0
    };
    score += lookahead;

    // 5. Alignment with mean residual
    let mean_align = -0.3
        * ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
    score += mean_align;

    // 6. Closeness to next item size (linear penalty)
    let closeness = (post_residual as i32 - next_item_size as i32).abs() as f64;
    score += -0.5 * closeness;

    // 7. Residual after reward: encourage very small residual
    score += -4.0 * res_after;

    // 8. New‑bin penalty (reduced when many bins already open)
    if bin_residual == bin_capacity {
        let new_pen = 4.0
            * (1.0 - (open_bins_count as f64).min(60.0) / 60.0)
            + 0.03 * open_bins_count as f64
            + 0.015 * mean_residual;
        score += new_pen;
    }

    // 9. Dead‑space penalty for large residual chunks
    if res_after > 0.3 {
        score += (res_after - 0.3).powi(2) * 5.0;
    }

    // 10. High‑usage reward: strongly reward bins that are almost full
    if used_ratio > 0.98 {
        score += - (used_ratio - 0.98).powi(2) * 15.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Stream progress and remaining items
    let progress = step_index as f64 / total_items as f64;
    let remaining_items = (total_items - step_index) as f64;
    let early_weight = (1.0 - progress).powi(2); // emphasize early decisions

    // Residual ratios before and after placement
    let residual_before = bin_residual as f64 / bin_capacity as f64;
    let residual_after  = post_residual  as f64 / bin_capacity as f64;

    // Base waste (lower is better)
    let waste = post_residual as f64;

    // 1️⃣ Early‑fit bias: keep larger residuals early
    let early_bias = -3.5
        * early_weight
        * residual_after
        * (open_bins_count as f64).sqrt();

    // 2️⃣ Unique‑fit penalty: bins with many alternatives are less attractive
    let unique_penalty = 1.3 * (fitting_bins_count as f64).ln().max(1.0);

    // 3️⃣ Tight‑fit reward: how well the item fills the bin
    let fit_frac = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    let fit_reward = -2.8 * fit_frac;

    // 4️⃣ Look‑ahead: reward/penalise depending on next item fit
    let lookahead = if next_item_size <= post_residual {
        // next item fits – reward remaining space proportionally
        -1.0 * ((post_residual - next_item_size) as f64).sqrt()
    } else {
        // next item does not fit – penalise heavily
        ((next_item_size - post_residual) as f64).powi(3) * 0.015
    };

    // 5️⃣ Mean‑deviation penalty: avoid bins far from average residual
    let mean_dev = (mean_residual - post_residual as f64).abs();
    let mean_penalty = 0.13 * mean_dev;

    // 6️⃣ Closeness reward: residual close to next item size is good
    let closeness = (post_residual as i32 - next_item_size as i32).abs() as f64;
    let closeness_reward = -0.7 * closeness.sqrt();

    // 7️⃣ Residual‑ratio reward: smaller residual after placement is desirable
    let residual_reward = -4.0 * residual_after;

    // 8️⃣ New‑bin penalty – reduced if many bins already open
    let new_bin_penalty = if bin_residual == bin_capacity {
        6.2 + 0.12 * open_bins_count as f64 + 0.04 * mean_residual
    } else {
        0.0
    };

    // Total score: lower is better
    waste
        + early_bias
        + unique_penalty
        + fit_reward
        + lookahead
        + mean_penalty
        + closeness_reward
        + residual_reward
        + new_bin_penalty
}
